12	// This file holds the single-record rules shared by the two on-disk sources:
13	// the registry file (decode, where stored text is already authoritative) and
14	// an import manifest (ParseManifest, where text is normalized on the way in).
15	// Both sources accept exactly the same four lowercase fields with the same
16	// strict JSON decoding — case-sensitive names, escaped spellings counted,
17	// duplicates visible, strict UTF-8 and strict JSON-integer quantities. The
18	// source-specific differences live in the callers:
19	//
20	//   - text policy: registry records are read verbatim (an empty string is a
21	//     format-level problem handled later by validate), while manifest text is
22	//     trimmed and must stay non-empty;
23	//   - which problem is reported first when one object has several: registry
24	//     records reject any duplicated field before an unknown one, manifest
25	//     records reject whichever anomaly appears first in source order;
26	//   - error types and reason wording, which remain owned by each caller.
27	type textPolicy int
28	
29	const (
30		textVerbatim textPolicy = iota // registry record: decode, keep as written
31		textTrimmed                    // manifest record: trim ends, reject blank
32	)
33	
34	// unambiguousBatchID returns the record's batch id only when it can be
35	// determined uniquely and reliably: exactly one "batch" member (counted after
36	// JSON key decoding, so an escaped respelling is the same member) holding one
37	// JSON string whose decoded text is valid UTF-8 and, under textTrimmed,
38	// non-blank after trimming. A missing, duplicated, mistyped, malformed or
39	// blank member yields "" — never a U+FFFD substitution and never one of two
40	// repeated values picked arbitrarily. The trimmed policy returns the
41	// normalized id; the verbatim policy returns the decoded text untouched.
42	func unambiguousBatchID(fields []objectField, policy textPolicy) string {
43		if countField(fields, "batch") != 1 {
44			return ""
45		}
46		raw, ok := findField(fields, "batch")
47		if !ok {
48			return ""
49		}
50		id, err := unmarshalStringStrict(raw)
51		if err != nil {
52			return ""
53		}
54		if policy == textTrimmed {
55			normalized, err := NormalizeField(id)
56			if err != nil {
57				return ""
58			}
59			id = normalized
60		}
61		return id
62	}
63	
64	// memberFault identifies one structural problem with an object's field names.
65	type memberFaultKind int
66	
67	const (
68		faultNone memberFaultKind = iota
69		faultDuplicate
70		faultUnknown
71	)
72	
73	type memberFault struct {
74		field string
75		kind  memberFaultKind
76	}
77	
78	// checkRecordMembers validates the member names of one batch record against
79	// batchRecordFields. With duplicatesFirst it reports the first member name
80	// that repeats anywhere in the object, and only reports an unknown member
81	// when nothing is repeated — the registry file rule. Otherwise it reports
82	// the first anomaly encountered in source order, be it an unknown member or
83	// a repeat — the manifest rule. In source order, an unknown name outranks a
84	// repeat on the same member, matching the original per-member scan. Repeated
85	// keys are detected on the decoded name, so a field hidden behind a JSON
86	// escape is the same member.
87	func checkRecordMembers(fields []objectField, duplicatesFirst bool) memberFault {
88		seen := make(map[string]struct{}, len(fields))
89		var firstDuplicate, firstUnknown memberFault
90		for _, f := range fields {
91			_, known := batchRecordFields[f.key]
92			_, repeated := seen[f.key]
93			seen[f.key] = struct{}{}
94			if !duplicatesFirst {
95				if !known {
96					return memberFault{field: f.key, kind: faultUnknown}
97				}
98				if repeated {
99					return memberFault{field: f.key, kind: faultDuplicate}
100				}
101				continue
102			}
103			if repeated && firstDuplicate.kind == faultNone {
104				firstDuplicate = memberFault{field: f.key, kind: faultDuplicate}
105			}
106			if !known && firstUnknown.kind == faultNone {
107				firstUnknown = memberFault{field: f.key, kind: faultUnknown}
108			}
109		}
110		if duplicatesFirst {
111			if firstDuplicate.kind != faultNone {
112				return firstDuplicate
113			}
114			return firstUnknown
115		}
116		return memberFault{}
117	}
118	
119	// fieldProblem classifies what is wrong with one text member's value,
120	// independently of the error wording each source presents.
121	type fieldProblem int
122	
123	const (
124		fieldOK fieldProblem = iota
125		fieldMissing
126		fieldNotString
127		fieldEncoding
128		fieldBlank
129	)
130	
131	// decodeRecordText reads one text member. found says whether the member
132	// exists; raw is its JSON value. Under textVerbatim every syntactically and
133	// encoding-valid string is returned as written, including "". Under
134	// textTrimmed the value must additionally be non-empty after trimming
135	// (NormalizeField); in that case cause carries NormalizeField's error so the
136	// caller can keep the established reason wording.
137	func decodeRecordText(raw json.RawMessage, found bool, policy textPolicy) (value string, problem fieldProblem, cause error) {
138		if !found {
139			return "", fieldMissing, nil
140		}
141		if trimmed := bytes.TrimSpace(raw); len(trimmed) == 0 || trimmed[0] != '"' {
142			return "", fieldNotString, nil
143		}
144		value, err := unmarshalStringStrict(raw)
145		if errors.Is(err, errStringEncoding) {
146			return "", fieldEncoding, nil
147		}
148		if err != nil {
149			return "", fieldNotString, nil
150		}
151		if policy == textTrimmed {
152			normalized, normErr := NormalizeField(value)
153			if normErr != nil {
154				// After strict decoding the only remaining failure is a blank
155				// result, but keep the cause rather than re-stating its text.
156				return "", fieldBlank, normErr
157			}
158			value = normalized
159		}
160		return value, fieldOK, nil
161	}
162	
163	// quantityShape classifies a JSON quantity token without assigning source-
164	// specific wording. The token is the trimmed raw JSON value; the callers
165	// decide how each class is phrased for registry files versus manifests.
166	type quantityShape int
167	
168	const (
169		qtyValid       quantityShape = iota
170		qtyNotNumeric                // value does not even start as a JSON number digit
171		qtyFractional                // digits followed by '.', 'e' or another non-digit
172		qtyLeadingZero               // "01": no conforming JSON document can reach this
173		qtyOutOfRange                // all digits, but outside signed 64-bit range
174		qtyZero
175	)
176	
177	// classifyJSONQuantity is the shared numeric rule: a strict JSON integer
178	// token (no sign, fraction or exponent) in 1..MaxQuantity. It only inspects
179	// token shape and range — never the surrounding object — so both on-disk
180	// sources and every future caller maintain one quantity definition.
181	func classifyJSONQuantity(token []byte) (int64, quantityShape) {
182		if len(token) == 0 || token[0] < '0' || token[0] > '9' {
183			return 0, qtyNotNumeric
184		}
185		for _, c := range token {
186			if c < '0' || c > '9' {
187				return 0, qtyFractional
188			}
189		}
190		if len(token) > 1 && token[0] == '0' {
191			return 0, qtyLeadingZero
192		}
193		value, err := strconv.ParseInt(string(token), 10, 64)
194		if err != nil {
195			return 0, qtyOutOfRange
196		}
197		if value == 0 {
198			return 0, qtyZero
199		}
200		return value, qtyValid
201	}
202	
203	// recordTextField is one of the three textual members every record carries.
204	type recordTextField struct {
205		name  string
206		value string
207	}
208	
209	// recordTextFields lists batch, product and unit in the fixed order in which
210	// per-field problems are reported, so every validation entry point iterates
211	// the same three members.
212	func recordTextFields(batch, product, unit string) []recordTextField {
213		return []recordTextField{
214			{"batch", batch},
215			{"product", product},
216			{"unit", unit},
217		}
218	}
219	
220	// safeBatchIDForError returns id exactly when it may be cited in an error:
221	// non-empty and valid UTF-8. An empty or malformed id yields "" so no value
222	// and no U+FFFD substitution is ever invented to name a batch.
223	func safeBatchIDForError(id string) string {
224		if id != "" && utf8.ValidString(id) {
225			return id
226		}
227		return ""
228	}
229	
230	// textIssueKind classifies one problem with an already-decoded text field.
231	type textIssueKind int
232	
233	const (
234		textEmpty    textIssueKind = iota // the empty string; whitespace-only text is not empty
235		textEncoding                      // the bytes are not valid UTF-8
236	)
237	
238	// textIssue is one problem with one text field of an already-decoded record.
239	type textIssue struct {
240		field string // "batch", "product" or "unit"
241		kind  textIssueKind
242	}
243	
244	// inspectRecordText examines the three text fields of an already-decoded
245	// record and lists every problem found, in the fixed batch, product, unit
246	// field order with a field's encoding problem listed before its empty-string
247	// problem. Text is checked verbatim — no trimming, no case folding — so
248	// whitespace-only text counts as ordinary non-empty text. This is the single
249	// definition of the text rules for the three entry points that validate
250	// decoded records (Register, Import and Save); each of them picks which issue
251	// to report first according to its own documented ordering.
252	func inspectRecordText(batch, product, unit string) []textIssue {
253		var issues []textIssue
254		for _, tv := range recordTextFields(batch, product, unit) {
255			if !utf8.ValidString(tv.value) {
256				issues = append(issues, textIssue{field: tv.name, kind: textEncoding})
257			}
258			if tv.value == "" {
259				issues = append(issues, textIssue{field: tv.name, kind: textEmpty})
260			}
261		}
262		return issues
263	}
264	
265	// firstTextIssue returns the first issue of the given kind, if any.
266	func firstTextIssue(issues []textIssue, kind textIssueKind) (textIssue, bool) {
267		for _, issue := range issues {
268			if issue.kind == kind {
269				return issue, true
270			}
271		}
272		return textIssue{}, false
273	}
274	
275	// decodedQuantityProblem classifies an already-decoded quantity against the
276	// accepted 1..MaxQuantity window shared by every entry point.
277	type decodedQuantityProblem int
278	
279	const (
280		decodedQtyOK decodedQuantityProblem = iota
281		decodedQtyNotPositive
282		decodedQtyAboveMax
283	)
284	
285	// classifyDecodedQuantity is the single quantity rule for already-decoded
286	// records; the callers decide how each class is phrased.
287	func classifyDecodedQuantity(quantity int64) decodedQuantityProblem {
288		switch {
289		case quantity <= 0:
290			return decodedQtyNotPositive
291		case quantity > MaxQuantity:
292			return decodedQtyAboveMax
293		default:
294			return decodedQtyOK
295		}
296	}
297	
298	// quantityInRange reports whether an already-decoded quantity lies in the
299	// accepted 1..MaxQuantity window shared by every entry point.
300	func quantityInRange(quantity int64) bool {
301		return classifyDecodedQuantity(quantity) == decodedQtyOK
302	}
303	
304	// These wrappers keep the registry-specific reason strings next to the
305	// registry parser while sharing classifyJSONQuantity; the wording predates
306	// the shared classifier and must not change.
307	func registryQuantityError(token []byte) (int64, error) {
308		value, shape := classifyJSONQuantity(token)
309		switch shape {
310		case qtyValid:
311			return value, nil
312		case qtyZero:
313			return 0, errors.New("must be greater than zero")
314		case qtyOutOfRange:
315			return 0, fmt.Errorf("must be an integer no greater than %d", MaxQuantity)
316		case qtyLeadingZero:
317			// No conforming JSON token reaches this branch (leading zeros fail the
318			// document scan); historically such a digit run was parsed on its
319			// numeric value, so keep that exact behavior.
320			parsed, err := strconv.ParseInt(string(token), 10, 64)
321			if err != nil {
322				return 0, fmt.Errorf("must be an integer no greater than %d", MaxQuantity)
323			}
324			if parsed == 0 {
325				return 0, errors.New("must be greater than zero")
326			}
327			return parsed, nil
328		default: // qtyNotNumeric, qtyFractional
329			return 0, fmt.Errorf("must be a JSON integer between 1 and %d", MaxQuantity)
330		}
331	}
332	
333	// manifestQuantityError mirrors the manifest wording: non-numeric values and
334	// signed numbers point at the accepted range, while fractions, exponents and
335	// (defensively) leading zeros each keep their own sentence.
336	func manifestQuantityError(token []byte) (int64, error) {
337		value, shape := classifyJSONQuantity(token)
338		switch shape {
339		case qtyValid:
340			return value, nil
341		case qtyZero:
342			return 0, errors.New(`field "quantity" must be greater than zero`)
343		case qtyLeadingZero:
344			return 0, errors.New(`field "quantity" must be a JSON integer without leading zeros`)
345		case qtyFractional:
346			return 0, errors.New(`field "quantity" must be a JSON integer without sign, fraction or exponent`)
347		case qtyOutOfRange:
348			return 0, fmt.Errorf(`field %q must be an integer no greater than %d`, "quantity", MaxQuantity)
349		default: // qtyNotNumeric
350			return 0, fmt.Errorf(`field %q must be a JSON integer between 1 and %d`, "quantity", MaxQuantity)
351		}
